"""Parallel AES-GCM using independent counter-aligned GCM stripes."""
import _fast
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

class Solver:
    def solve(self, p, **kwargs):
        try:
            ciphertext, tag = _fast.encrypt(
                p["key"], p["nonce"], p["plaintext"], p["associated_data"])
        except ValueError:
            result = AESGCM(p["key"]).encrypt(
                p["nonce"], p["plaintext"], p["associated_data"])
            ciphertext, tag = result[:-16], result[-16:]
        return {"ciphertext": ciphertext, "tag": tag}

